            check(lanes.execute(0,()->{try{String verified=aPolicy.readyRun(laneClock,()->liveSigner.current(liveScope,true));aReply.complete(GatewayGrantIssuer.issueTargets(liveSigner,liveScope,checked,Collections.singletonList(cfgA.observedRun(verified)),new GatewaySequenceStore(new GatewayIssuerTest.Storage()),WALL,true,()->liveSigner.current(liveScope,true)));}catch(Exception failed){aReply.completeExceptionally(failed);}}));
